Lemma dp_find_fn : forall (m : nat) regs (M rom : word -> option byte) (l2 N h cur : Z),
  (Z.to_nat cur <= m)%nat ->
  cellA M MAP1 8 l2 -> 4096 <= l2 -> l2 + 2 ^ 20 < 2 ^ 64 -> l2 mod 16 = 0 -> 0 <= N < 2 ^ 16 -> dp_nodes M l2 N ->
  0 <= cur <= N -> 0 <= h < 2 ^ 64 ->
  getr regs 11 = Z_to_bv 64 cur -> getr regs 19 = Z_to_bv 64 h -> getr regs 24 = Z_to_bv 64 MAP1 -> getr regs 22 = Z_to_bv 64 65535 ->
  exists regs',
    ((msteps ASEGS (mkst regs (0x9b2b0 : word) M rom) (mkst regs' (0x9b308 : word) M rom) /\ getr regs' 11 = Z_to_bv 64 0 /\ ~ dp_chain M l2 h cur)
     \/ (msteps ASEGS (mkst regs (0x9b2b0 : word) M rom) (mkst regs' (0x9b3b4 : word) M rom) /\ (exists id, 1 <= id <= N /\ getr regs' 10 = Z_to_bv 64 id) /\ dp_chain M l2 h cur))
